      remember (((bv_unsigned c ≪ b) mod 18446744073709551616) ≫ 53) as v eqn:EV; clear EV end.

  Ltac y4c v c EC :=
    lazymatch goal with TCK : forall i, 0 <= i < 2^11 -> _, VR : 0 <= v < 2048 |- _ =>
